## 3. Result-Generation Logic (form data → recommendation)

Logic is defined inline in the Compass page (no separate lib file) as the `defaultInputs` object and the `evaluate()` function.

Source: `client/src/pages/NarcolepsyCompass.tsx`

```typescript
interface NarcolepsyInputs {
  ess: string;
  cataplexy: boolean;
  sleepParalysis: boolean;
  hypnagogicHallucinations: boolean;
  automaticBehavior: boolean;
  disrupted_nocturnal_sleep: boolean;
  mslt_sol: string;
  mslt_sorems: string;
  csf_hypocretin: string;
  psg_performed: boolean;
  psg_rem_latency: string;
  type: "type1" | "type2" | "unknown";
  current_stimulant: boolean;
  current_sodium_oxybate: boolean;
  current_pitolisant: boolean;
  current_solriamfetol: boolean;
  prior_treatment_failed: boolean;
  comorbid_osa: boolean;
  comorbid_depression: boolean;
  comorbid_anxiety: boolean;
}

const defaultInputs: NarcolepsyInputs = {
  ess: "",
  cataplexy: false,
  sleepParalysis: false,
  hypnagogicHallucinations: false,
  automaticBehavior: false,
  disrupted_nocturnal_sleep: false,
  mslt_sol: "",
  mslt_sorems: "",
  csf_hypocretin: "not_tested",
  psg_performed: false,
  psg_rem_latency: "",
  type: "unknown",
  current_stimulant: false,
  current_sodium_oxybate: false,
  current_pitolisant: false,
  current_solriamfetol: false,
  prior_treatment_failed: false,
  comorbid_osa: false,
  comorbid_depression: false,
  comorbid_anxiety: false,
};

function evaluate(inputs: NarcolepsyInputs) {
  const essNum = parseFloat(inputs.ess);
  const msltSol = parseFloat(inputs.mslt_sol);
  const msltSorems = parseInt(inputs.mslt_sorems);
  const psgRemLatency = parseFloat(inputs.psg_rem_latency);

  const excessiveDaytimeSleepiness = essNum >= 10;
  const msltPositive = msltSol <= 8 && msltSorems >= 2;
  const csfLow = inputs.csf_hypocretin === "low";
  const psgSoremPresent = inputs.psg_performed && psgRemLatency <= 15;

  // ICSD-3 / AASM 2021 criteria
  let diagnosisLikelihood: "high" | "moderate" | "low" = "low";
  let diagnosisType = inputs.type;

  if (inputs.cataplexy && (csfLow || msltPositive)) {
    diagnosisLikelihood = "high";
    diagnosisType = "type1";
  } else if (!inputs.cataplexy && msltPositive && !csfLow) {
    diagnosisLikelihood = "high";
    diagnosisType = "type2";
  } else if (excessiveDaytimeSleepiness && (msltPositive || psgSoremPresent)) {
    diagnosisLikelihood = "moderate";
  } else if (excessiveDaytimeSleepiness) {
    diagnosisLikelihood = "low";
  }

  // Treatment recommendations per AASM 2021 CPG
  const firstLine: string[] = [];
  const secondLine: string[] = [];
  const adjunctive: string[] = [];

  if (diagnosisLikelihood !== "low") {
    // EDS treatment
    firstLine.push("Modafinil 100–400 mg/day (AASM: Strong recommendation)");
    firstLine.push("Pitolisant 17.8–35.6 mg/day (AASM: Strong recommendation)");
    firstLine.push("Sodium oxybate 4.5–9 g/night in 2 divided doses (AASM: Strong recommendation)");
    firstLine.push("Solriamfetol 75–150 mg/day (AASM: Strong recommendation)");

    if (diagnosisType === "type1" || inputs.cataplexy) {
      firstLine.push("Sodium oxybate (also addresses cataplexy — AASM: Strong recommendation)");
      firstLine.push("Pitolisant (also addresses cataplexy — AASM: Conditional recommendation)");
      secondLine.push("Venlafaxine 75–225 mg/day for cataplexy (AASM: Conditional)");
      secondLine.push("Clomipramine 25–200 mg/day for cataplexy (AASM: Conditional)");
    }

    adjunctive.push("Scheduled naps (15–20 min, 1–2x/day)");
    adjunctive.push("Sleep hygiene counseling");
    adjunctive.push("Driving restrictions counseling per state law");
  }

  const authRequired = diagnosisLikelihood !== "low";
  const appealStrength: "strong" | "moderate" | "weak" =
    diagnosisLikelihood === "high" ? "strong" : diagnosisLikelihood === "moderate" ? "moderate" : "weak";

  const keyFindings: string[] = [];
  if (excessiveDaytimeSleepiness) keyFindings.push(`ESS score ${essNum} (≥10 indicates EDS)`);
  if (inputs.cataplexy) keyFindings.push("Cataplexy present (pathognomonic for NT1)");
  if (msltPositive) keyFindings.push(`MSLT: SOL ≤8 min with ≥2 SOREMPs (AASM diagnostic threshold met)`);
  if (csfLow) keyFindings.push("CSF hypocretin-1 ≤110 pg/mL (diagnostic for NT1)");
  if (psgSoremPresent) keyFindings.push(`PSG: REM latency ≤15 min (sleep-onset REM period)`);
  if (inputs.comorbid_osa) keyFindings.push("Comorbid OSA — ensure adequate OSA treatment before MSLT");

  return {
    diagnosisLikelihood,
    diagnosisType,
    authRequired,
    appealStrength,
    firstLine,
    secondLine,
    adjunctive,
    keyFindings,
    essNum,
    msltPositive,
    csfLow,
  };
}
